# region: sift
def sift(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: digest
def digest(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return digest(shape(intake(sift(raw))))

